/**
 * The derived XSD inventory of the SSML 1.1 vocabulary: one entry per kind handle, 20 entries.
 *
 * Generated by `node src/vocab/derive/ssml.ts` over `ssml/synthesis-nonamespace.xsd` and
 * `ssml/ssmlv1p1-core.xsd` and formatted with `vp fmt`; `src/vocab/derive/ssml.test.ts` checks that
 * a re-run reproduces this file byte for byte. Attribute declarations by `whiteSpace` class over
 * these entries: collapse 32, preserve 22, replace 0, union 10.
 *
 * The schema is the no-namespace file as the core profile redefines it into the synthesis
 * namespace, so `speak/@version`, `speak/@xml:lang` and `mark/@name` are required. Built-in types
 * are spelled `xs:`, as in the ASI leaves. The reading rules are `src/vocab/derive/ssml.ts`'s.
 *
 * A choice group's members each carry the group's bounds multiplied into their own, so a member of
 * a `(a | b){1..n}` group reads `{ min: 1, max: None }`. The choice groups of two to six members,
 * by entry (the larger groups are the twelve members of the `aws` substitution group and the
 * content choices of 9 to 16 names, all `0..n` but those of `speak`'s first sentence-and-structure
 * choice, which are `0..1`):
 *
 * - `ssml:audio`: (p | s){0..n}
 * - `ssml:prosody`: (p | s){0..n}
 * - `ssml:speak`: (meta | metadata | lexicon){0..n}; (p | s){0..1}; (p | s){0..n}
 * - `ssml:voice`: (p | s){0..n}
 */
import { Option } from "effect";

import type {
  InventoryAttribute,
  InventoryChild,
  InventoryLeaf,
} from "#pantry/schema/content/xsd-inventory.ts";

/**
 * Build an attribute row from its declaration.
 *
 * @param name - The attribute name as the XSD spells it.
 * @param type - The declared type name, or the base of an inline type.
 * @param use - Whether the XSD requires the attribute.
 * @param family - Which attribute family the name belongs to.
 * @param whiteSpace - The `whiteSpace` class of the declared type.
 * @param defaultValue - The XSD `default`, absent when none is declared.
 * @returns The attribute row.
 */
const attribute = (
  name: string,
  type: string,
  use: InventoryAttribute["use"],
  family: InventoryAttribute["family"],
  whiteSpace: InventoryAttribute["whiteSpace"],
  defaultValue?: string,
): InventoryAttribute => ({
  default: Option.fromNullishOr(defaultValue),
  family,
  name,
  type,
  use,
  whiteSpace,
});

/**
 * Build a child row from an element reference.
 *
 * @param name - The referenced element name as the XSD spells it.
 * @param min - The effective minimum occurrence.
 * @param max - The effective maximum occurrence, `None` when unbounded.
 * @returns The child row.
 */
const child = (name: string, min: number, max: Option.Option<number>): InventoryChild => ({
  max,
  min,
  name,
});

